import { test, expect } from "@playwright/test";
import { mkdir, mkdtemp, writeFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { configuration, createService, startServer } from "../../server.mjs";

let server, service, workspace;
test.beforeAll(async () => {
  if (!process.env.NIXTLA_E2E_OUTPUT) throw new Error("Set NIXTLA_E2E_OUTPUT to an explicit disposable directory.");
  await mkdir(process.env.NIXTLA_E2E_OUTPUT, { recursive: true });
  workspace = await mkdtemp(join(resolve(process.env.NIXTLA_E2E_OUTPUT), "explorer-"));
  const { runtime, contract } = await configuration();
  service = createService({ workspace, python: runtime.python, contract });
  await service.call("initialize", {});
  const source = join(workspace, "Monthly-revenue-history-with-a-long-descriptive-name.csv");
  const rows = ["unique_id,ds,y"];
  for (let i = 0; i < 48; i++) rows.push(`001,${2020 + Math.floor(i / 12)}-${String(i % 12 + 1).padStart(2, "0")}-01,${100 + i}`);
  await writeFile(source, rows.join("\n"));
  await service.call("profile", { path: source, horizon: 3 });
  const run = join(workspace, "original");
  await mkdir(join(run, "audit"), { recursive: true });
  await writeFile(join(run, "manifest.json"), JSON.stringify({ spec: { freq: "MS", horizon: 1 } }));
  await writeFile(join(run, "forecast.csv"), "unique_id,ds,yhat\n001,2025-01-01,12345678901234.56789\n");
  await writeFile(join(run, "audit", "review-notes.md"), "# Synthetic review\nSaved evidence, not an execution request.");
  const imported = await service.call("import_run", { path: run, name: "Revenue" });
  await service.call("save_note", { runId: imported.id, body: "A saved seasonality finding." });
  server = await startServer({ workspace, service, handoff: async () => {} });
});
test.afterAll(async () => { await server?.close(); await service?.close(); });

test("explorer opens real files and protected data, searches all types and remembers folders", async ({ page }) => {
  const errors = [];
  page.on("pageerror", error => errors.push(error.message));
  await page.goto(server.url);
  const explorer = page.getByRole("navigation", { name: "Forecasts, data and files" });
  await explorer.getByRole("button", { name: /^Revenue/ }).click();
  await explorer.getByRole("button", { name: /^Versions/ }).click();
  const version = explorer.locator(".explorer-toggle").filter({ hasText: /\d{4}.*·/ });
  await version.click();
  await explorer.getByRole("button", { name: "Files", exact: true }).click();
  await explorer.getByRole("button", { name: "forecast.csv", exact: true }).click();
  const preciseCell = page.getByRole("region", { name: "Saved file values" }).getByRole("cell", { name: "12,345,678,901,234.57", exact: true });
  await expect(preciseCell).toBeVisible();
  await expect(preciseCell).toHaveAttribute("title", "12345678901234.56789");
  await expect(page.getByText("Saved file · read-only")).toBeVisible();
  await explorer.getByRole("button", { name: "audit", exact: true }).click();
  await explorer.getByRole("button", { name: "review-notes.md", exact: true }).click();
  await expect(page.locator(".file-preview")).toContainText("not an execution request");
  await expect(page.getByRole("status").filter({ hasText: "Saved locally" })).toBeVisible();
  await page.reload();
  await expect(explorer.getByRole("button", { name: "audit", exact: true })).toHaveAttribute("aria-expanded", "true");
  await expect(page.locator(".file-preview")).toContainText("Synthetic review");
  await explorer.getByRole("button", { name: /^Monthly-revenue-history/ }).click();
  await expect(page.getByRole("heading", { name: "Saved data snapshot" })).toBeVisible();
  await expect(page.getByText("3 protected observations remain withheld", { exact: false })).toBeVisible();
  await expect(page.getByRole("region", { name: "Saved source values" })).toContainText("001");
  expect((await service.call("catalog", {})).jobs).toHaveLength(0);
  await page.screenshot({ path: join(workspace, "explorer-desktop.png") });
  await page.getByLabel("Search library").fill("review-notes");
  await expect(explorer.getByRole("button", { name: /audit\/review-notes.md/ })).toBeVisible();
  await page.getByLabel("Search library").fill("seasonality");
  await explorer.getByRole("button", { name: /A saved seasonality finding/ }).click();
  await expect(page.getByRole("button", { name: "Research", exact: true })).toHaveClass("selected");
  await page.getByLabel("Search library").fill("no-such-saved-item");
  await expect(explorer.getByText("Nothing saved here yet.")).toBeVisible();
  await page.getByRole("button", { name: "Clear library search" }).click();
  const data = explorer.getByRole("button", { name: /^Data \d/ });
  await data.focus();
  await page.keyboard.press("ArrowLeft");
  await expect(data).toHaveAttribute("aria-expanded", "false");
  await page.keyboard.press("ArrowRight");
  await expect(data).toHaveAttribute("aria-expanded", "true");
  await expect(explorer.getByRole("button", { name: /^Monthly-revenue-history/ })).toBeVisible();
  await explorer.getByRole("button", { name: /^Monthly-revenue-history/ }).click();
  // Emulate a source beyond the initial catalog page without hiding it from the explorer.
  await page.route("**/api", async route => {
    if (route.request().postDataJSON().operation !== "catalog") return route.continue();
    const response = await route.fetch();
    const body = await response.json();
    body.result.sources = [];
    await route.fulfill({ response, json: body });
  });
  const catalogRefresh = page.waitForResponse(response => response.url().endsWith("/api") && response.request().postDataJSON().operation === "catalog");
  await page.getByRole("button", { name: "Refresh saved catalog" }).click();
  await catalogRefresh;
  await page.getByRole("button", { name: "Use for a forecast" }).click();
  await expect(page.getByLabel("Snapshot")).not.toHaveValue("");
  await expect(page.getByLabel("Snapshot").locator("option:checked")).toContainText("Monthly-revenue-history");
  expect((await service.call("catalog", {})).jobs).toHaveLength(0);
  await page.setViewportSize({ width: 620, height: 900 });
  await page.screenshot({ path: join(workspace, "explorer-narrow.png") });
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
  expect(await explorer.evaluate(nav => [...nav.querySelectorAll("button")].every(button => button.getBoundingClientRect().right <= nav.getBoundingClientRect().right + 1))).toBe(true);
  expect(errors).toEqual([]);
  console.log(`Explorer evidence: ${workspace}`);
});
